#pragma once

/*
 * TinySLED heading and status LEDs (docs/spec.md, "Heading and status LED").
 *
 * PIN_HEAD_LED drives the AO3402 low-side switch Q1 (high = lit). Every
 * pulse is a one-shot generated by a PIO state machine (head_led.pio), so
 * on-time and duty are capped in hardware: a pulse can never exceed the
 * PIO counter (~655 ms) and is always followed by at least three times its
 * length off (duty <= 25%). If firmware hangs the queue drains and the LED
 * stays dark.
 *
 * Spinning with a fresh heading estimate: one 400 us strobe per revolution,
 * centred on the reference heading, painting a stationary dot for "front."
 * Otherwise the LED blinks the current status code.
 */

#include <stdint.h>
#include "estimation/heading_estimate.h"

typedef enum {
    HEAD_LED_NO_LINK = 0,   /* boot, RC link never seen */
    HEAD_LED_DISARMED,
    HEAD_LED_ARMED,
    HEAD_LED_LOW_BATTERY,
    HEAD_LED_FAILSAFE,      /* RC link lost or stale after being up */
    HEAD_LED_IMU_FAULT,
} head_led_status_t;

void head_led_init(void);

/* Select the status pattern shown while not spinning. */
void head_led_set_status(head_led_status_t status);

/* Feed a fresh heading estimate (call when a new one is available). */
void head_led_on_estimate(const heading_estimate_t *est, uint32_t now_us);

/* Queue the next strobe or status blink. Call every control-loop iteration. */
void head_led_tick(uint32_t now_us);
